package com.cpf.education.online.querypaging.controller;
import com.cpf.education.online.querypaging.dto.*;import com.cpf.education.online.querypaging.service.MemberSearchService;import com.cpf.foundation.execution.api.CpfOnlineTransaction;import com.cpf.web.api.CpfRestController;import io.swagger.v3.oas.annotations.Operation;import org.springframework.web.bind.annotation.*;
/** 조회·검색·Paging 교육 예제의 Controller 역할과 CPF 표준 사용 경계를 보여줍니다. */
@CpfRestController @RequestMapping("/edu/online/member-search") public class MemberSearchController {private final MemberSearchService service;public MemberSearchController(MemberSearchService s){service=s;}@GetMapping @Operation(operationId="EDU_MEMBER_SEARCH",summary="조회·검색·Paging 거래") @CpfOnlineTransaction(operationId="EDU_MEMBER_SEARCH",name="조회·검색·Paging 거래",description="CPF Paging/Sort 계약으로 조건조회하고 COUNT 필요 여부에 따라 Page/Slice/상세를 선택한다.") public SearchResult search(@RequestParam(defaultValue="PAGE") SearchMode mode,@RequestParam(required=false) String memberId,@RequestParam(required=false) String name,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return service.search(mode,memberId,name,page,size);}}
